import React from 'react';
import { NavLink } from 'react-router-dom';
import { useAuth } from '../context/AuthContext';
import { useTheme } from '../context/ThemeContext';

const links = [
  { to: '/dashboard', label: 'Dashboard', icon: '🏠' },
  { to: '/assessment', label: 'Assessment', icon: '📋' },
  { to: '/analytics', label: 'Analytics', icon: '📊' },
  { to: '/recommendations', label: 'Recommendations', icon: '💡' },
  { to: '/profile', label: 'Profile', icon: '👤' },
];

export default function Sidebar() {
  const { user, logout } = useAuth();
  const { theme, toggle } = useTheme();

  return (
    <aside className="sidebar p-3 d-flex flex-column" style={{ minHeight: '100vh', background: 'var(--mw-sidebar)', color: '#fff' }}>
      <div className="mb-4">
        <h5 className="mb-0 fw-bold">MindWatch AI</h5>
        <small className="text-white-50">Mental Health Monitor</small>
      </div>
      <nav className="nav flex-column gap-1 flex-grow-1">
        {links.map((l) => (
          <NavLink key={l.to} to={l.to} className={({ isActive }) => `nav-link text-white-50 ${isActive ? 'active bg-primary rounded' : ''}`}>
            {l.icon} {l.label}
          </NavLink>
        ))}
        {user?.isAdmin && (
          <NavLink to="/admin" className={({ isActive }) => `nav-link text-white-50 ${isActive ? 'active bg-danger rounded' : ''}`}>
            ⚙️ Admin
          </NavLink>
        )}
      </nav>
      <button className="btn btn-outline-light btn-sm mb-2" onClick={toggle}>
        {theme === 'light' ? '🌙 Dark' : '☀️ Light'}
      </button>
      <button className="btn btn-danger btn-sm" onClick={logout}>Logout</button>
    </aside>
  );
}
